#include <stdlib.h>

struct Heap { int *a; int n, cap; };

static void swap(int *x, int *y) { int t = *x; *x = *y; *y = t; }

static void sift_up(struct Heap *h, int i) {
    while (i > 0) {
        int p = (i - 1) / 2;
        if (h->a[p] <= h->a[i]) break;
        swap(&h->a[p], &h->a[i]);
        i = p;
    }
}

static void sift_down(struct Heap *h, int i) {
    for (;;) {
        int l = 2 * i + 1, r = l + 1, m = i;
        if (l < h->n && h->a[l] < h->a[m]) m = l;
        if (r < h->n && h->a[r] < h->a[m]) m = r;
        if (m == i) return;
        swap(&h->a[i], &h->a[m]);
        i = m;
    }
}

int heap_push(struct Heap *h, int x) {
    if (h->n == h->cap) {
        int nc = h->cap ? 2 * h->cap : 8;
        int *na = realloc(h->a, nc * sizeof *na);
        if (!na) return -1;
        h->a = na; h->cap = nc;
    }
    h->a[h->n++] = x;
    sift_up(h, h->n - 1);
    return 0;
}

int heap_pop(struct Heap *h) {            /* caller checks h->n > 0 */
    int top = h->a[0];
    h->a[0] = h->a[--h->n];
    if (h->n) sift_down(h, 0);
    return top;
}

void heap_build(struct Heap *h, int *arr, int n) {
    h->a = arr; h->n = n; h->cap = n;
    for (int i = n / 2 - 1; i >= 0; i--)
        sift_down(h, i);
}

static void down(int *a, int n, int i) {      /* max-heap sift-down */
    for (;;) {
        int l = 2 * i + 1, r = l + 1, m = i;
        if (l < n && a[l] > a[m]) m = l;
        if (r < n && a[r] > a[m]) m = r;
        if (m == i) return;
        int t = a[i]; a[i] = a[m]; a[m] = t;
        i = m;
    }
}

void heap_sort(int *a, int n) {
    for (int i = n / 2 - 1; i >= 0; i--) down(a, n, i);   /* max-heap */
    for (int end = n - 1; end > 0; end--) {
        int t = a[0]; a[0] = a[end]; a[end] = t;
        down(a, end, 0);
    }
}

int is_min_heap(const int *a, int n) {
    for (int i = 0; i <= n / 2 - 1; i++) {
        int l = 2 * i + 1, r = l + 1;
        if (a[l] < a[i]) return 0;
        if (r < n && a[r] < a[i]) return 0;
    }
    return 1;
}
